{
  "name": "@aipno/opencode-token-monitor",
  "version": "1.0.6",
  "description": "Real-time token usage monitoring plugin for OpenCode with sidebar display",
  "type": "module",
  "main": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    },
    "./tui": {
      "types": "./dist/tui.d.ts",
      "import": "./dist/tui.jsx"
    },
    "./package.json": "./package.json"
  },
  "files": [
    "dist"
  ],
  "sideEffects": false,
  "scripts": {
    "build": "tsc",
    "prepublishOnly": ""
  },
  "engines": {
    "node": ">=18"
  },
  "keywords": [
    "opencode",
    "plugin",
    "opencode-plugin",
    "tokens",
    "usage",
    "monitor",
    "tui"
  ],
  "publishConfig": {
    "access": "public"
  },
  "license": "Apache-2.0",
  "devDependencies": {
    "@opencode-ai/plugin": "latest",
    "@opentui/core": "^0.2.9",
    "@opentui/solid": "^0.2.9",
    "@types/node": "^22.0.0",
    "solid-js": "^1.9.14",
    "typescript": "^5.7.0"
  }
}
